def count_divisors(n):
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            count += 2 if i*i != n else 1
    return count

def is_exotic(n):
    d_n = count_divisors(n)
    # Check if d_n is twice an odd integer
    if d_n % 2 == 0:
        odd_part = d_n // 2
        return odd_part % 2 != 0
    return False

# Iterate and count the exotic integers
exotic_integers = []
i = 1
target_count = 132

while len(exotic_integers) < target_count:
    if is_exotic(i):
        exotic_integers.append(i)
    i += 1

# The 132nd exotic integer
n_132 = exotic_integers[-1]
print(f"The 132th exotic integer is: {n_132}")
